import React from 'react';

const Motor3D = () => {
  return (
    <div className="motor-3d-container">
      <div className="motor-3d">
        {/* Motor Body */}
        <div className="motor-body">
          <div className="motor-face front"></div>
          <div className="motor-face back"></div>
          <div className="motor-face left"></div>
          <div className="motor-face right"></div>
          <div className="motor-face top"></div>
          <div className="motor-face bottom"></div>
        </div>

        {/* Motor Shaft */}
        <div className="motor-shaft"></div>

        {/* Cooling Fins */}
        <div className="cooling-fins">
          {[...Array(8)].map((_, i) => (
            <div key={i} className="fin" style={{transform: `rotateY(${i * 45}deg)`}}></div>
          ))}
        </div>

        {/* Terminal Box */}
        <div className="terminal-box"></div>

        {/* Motor Label */}
        <div className="motor-label">AC MOTOR</div>
      </div>
    </div>
  );
};

export default Motor3D;
